<?php require 'config.php';$id=(int)($_POST['id']??$_GET['id']??0);$qty=max(1,(int)($_POST['qty']??1));$q=$conn->prepare('SELECT product_id,stock FROM products WHERE product_id=?');$q->bind_param('i',$id);$q->execute();$p=$q->get_result()->fetch_assoc();if($p){if(!isset($_SESSION['cart']))$_SESSION['cart']=[];$_SESSION['cart'][$id]=min(($_SESSION['cart'][$id]??0)+$qty,(int)$p['stock']);}if($_SERVER['REQUEST_METHOD']==='POST'){header('Content-Type: application/json');echo json_encode(['ok'=>(bool)$p,'count'=>cart_count()]);exit;}header('Location: cart.php');exit;